	const HERO_VIDEO_SRC = resolve('/field-video.mp4')
	const HERO_VIDEO_BASE_RATE = 0.35
	const HERO_VIDEO_END_RATE = 0.08
	const HERO_VIDEO_EASE_DURATION = 4

	let videoEaseFrame = 0

	function easeOutVideo(event: Event) {
		if (!(event.currentTarget instanceof HTMLVideoElement)) return

		const video = event.currentTarget
		video.playbackRate = HERO_VIDEO_BASE_RATE
		cancelAnimationFrame(videoEaseFrame)

		function updatePlaybackRate() {
			if (video.paused || video.ended || !Number.isFinite(video.duration)) return

			const remaining = video.duration - video.currentTime
			const progress = Math.min(1, Math.max(0, 1 - remaining / HERO_VIDEO_EASE_DURATION))
			const easedProgress = 1 - (1 - progress) ** 3

			video.playbackRate =
				HERO_VIDEO_BASE_RATE - (HERO_VIDEO_BASE_RATE - HERO_VIDEO_END_RATE) * easedProgress

			videoEaseFrame = requestAnimationFrame(updatePlaybackRate)
		}

		videoEaseFrame = requestAnimationFrame(updatePlaybackRate)
	}

	onDestroy(() => {
		if (!browser) return

		cancelAnimationFrame(videoEaseFrame)
	})
