#!/usr/bin/env bun
/**
 * Creates Topaz Apollo slow-motion requests for the homepage field video
 */

import { createHash } from 'node:crypto'

import { readFile } from 'node:fs/promises'

const API_BASE = 'https://api.topazlabs.com'
const DEFAULT_INPUT = 'static/field-video.mp4'
const DEFAULT_MODEL = 'apo-8'
const DEFAULT_SLOWMO = 4
const DEFAULT_FPS = 60

type Command = 'estimate' | 'submit' | 'status'

type VideoProbe = {
	container: string
	duration: number
	frameCount: number
	frameRate: number
	resolution: {
		width: number
		height: number
	}
	size: number
}

type CreateResponse = {
	requestId?: string
	estimates?: {
		cost?: [number, number]
		time?: [number, number]
	}
}

type AcceptResponse = {
	message?: string
	uploadId?: string
	urls?: string[]
}

type UploadResult = {
	partNum: number
	eTag: string
}

type Options = {
	command: Command
	download?: string
	fps: number
	input: string
	model: string
	requestId?: string
	slowmo: number
}

function parseArgs(args: string[]) {
	const command = (args[0] ?? 'estimate') as Command
	const rest = ['estimate', 'submit', 'status'].includes(command) ? args.slice(1) : args

	const options: Options = {
		command: ['estimate', 'submit', 'status'].includes(command) ? command : 'estimate',
		fps: DEFAULT_FPS,
		input: DEFAULT_INPUT,
		model: DEFAULT_MODEL,
		slowmo: DEFAULT_SLOWMO
	}

	for (let i = 0; i < rest.length; i += 1) {
		const arg = rest[i]
		const [key, inlineValue] = arg.split('=', 2)
		const value = inlineValue ?? rest[i + 1]

		if (key === '--input') {
			options.input = requiredValue(key, value)
			if (!inlineValue) i += 1
		} else if (key === '--model') {
			options.model = requiredValue(key, value)
			if (!inlineValue) i += 1
		} else if (key === '--slowmo') {
			options.slowmo = Number(requiredValue(key, value))
			if (!inlineValue) i += 1
		} else if (key === '--fps') {
			options.fps = Number(requiredValue(key, value))
			if (!inlineValue) i += 1
		} else if (key === '--download') {
			options.download = requiredValue(key, value)
			if (!inlineValue) i += 1
		} else if (options.command === 'status' && !options.requestId && !arg.startsWith('--')) {
			options.requestId = arg
		} else if (arg === '--help' || arg === '-h') {
			printUsage()
			process.exit(0)
		} else {
			throw new Error(`Unknown argument: ${arg}`)
		}
	}

	if (!Number.isFinite(options.slowmo) || options.slowmo < 1 || options.slowmo > 16) {
		throw new Error('--slowmo must be a number between 1 and 16')
	}

	if (!Number.isFinite(options.fps) || options.fps < 15 || options.fps > 240) {
		throw new Error('--fps must be a number between 15 and 240')
	}

	return options
}

function requiredValue(key: string, value?: string) {
	if (!value || value.startsWith('--')) {
		throw new Error(`${key} requires a value`)
	}

	return value
}

function printUsage() {
	console.log(`Usage:
  bun scripts/topaz-slowmo.ts estimate [--input static/field-video.mp4] [--slowmo 4] [--fps 60]
  bun scripts/topaz-slowmo.ts submit [--input static/field-video.mp4] [--slowmo 4] [--fps 60]
  bun scripts/topaz-slowmo.ts status <request-id> [--download static/field-video-slowmo-4x-60fps.mp4]

Environment:
  TOPAZ  Topaz Labs API key`)
}

function getApiKey() {
	const key = process.env.TOPAZ
	if (!key) {
		throw new Error('TOPAZ is not set. Add it to .env or export it before running this script.')
	}

	return key
}

function maskKey(key: string) {
	return `${key.slice(0, 4)}...${key.slice(-4)}`
}

async function probeVideo(input: string): Promise<VideoProbe> {
	const file = Bun.file(input)
	const size = file.size
	const container = input.split('.').pop()?.toLowerCase() ?? 'mp4'
	const proc = Bun.spawn([
		'ffprobe',
		'-v',
		'error',
		'-select_streams',
		'v:0',
		'-show_entries',
		'stream=width,height,avg_frame_rate,r_frame_rate,nb_frames,duration',
		'-of',
		'json',
		input
	])

	const [stdout, stderr] = await Promise.all([
		new Response(proc.stdout).text(),
		new Response(proc.stderr).text()
	])
	const exitCode = await proc.exited

	if (exitCode !== 0) {
		throw new Error(`ffprobe failed for ${input}: ${stderr.trim() || stdout.trim()}`)
	}

	const parsed = JSON.parse(stdout)
	const stream = parsed.streams?.[0]
	if (!stream) throw new Error(`No video stream found in ${input}`)

	const frameRate = parseRate(stream.avg_frame_rate || stream.r_frame_rate)
	const duration = Number(stream.duration)
	const frameCount = Number(stream.nb_frames) || Math.round(duration * frameRate)

	return {
		container,
		duration,
		frameCount,
		frameRate,
		resolution: {
			width: Number(stream.width),
			height: Number(stream.height)
		},
		size
	}
}

function parseRate(rate: string) {
	const [num, den = '1'] = rate.split('/').map(Number)
	if (!num || !den) throw new Error(`Could not parse frame rate: ${rate}`)

	return num / den
}

function buildRequest(probe: VideoProbe, options: Options) {
	return {
		source: {
			resolution: probe.resolution,
			container: probe.container,
			size: probe.size,
			duration: probe.duration,
			frameRate: probe.frameRate,
			frameCount: probe.frameCount
		},
		output: {
			resolution: probe.resolution,
			audioCodec: 'AAC',
			audioTransfer: 'Copy',
			frameRate: options.fps,
			dynamicCompressionLevel: 'High',
			container: 'mp4'
		},
		filters: [
			{
				model: options.model,
				slowmo: options.slowmo,
				fps: options.fps,
				duplicate: true,
				duplicateThreshold: 0.01
			}
		]
	}
}

async function topazFetch<T>(path: string, init: RequestInit = {}) {
	const key = getApiKey()
	const response = await fetch(`${API_BASE}${path}`, {
		...init,
		headers: {
			'X-API-Key': key,
			accept: 'application/json',
			...init.headers
		}
	})

	const text = await response.text()
	const json = text ? JSON.parse(text) : undefined

	if (!response.ok) {
		throw new Error(`Topaz API ${response.status}: ${JSON.stringify(json ?? text)}`)
	}

	return json as T
}

async function createRequest(options: Options) {
	const probe = await probeVideo(options.input)
	const request = buildRequest(probe, options)

	printProbe(probe, options)

	const response = await topazFetch<CreateResponse>('/video/', {
		method: 'POST',
		headers: {
			'content-type': 'application/json'
		},
		body: JSON.stringify(request)
	})

	printEstimate(response)
	return response
}

function printProbe(probe: VideoProbe, options: Options) {
	const outputDuration = probe.duration * options.slowmo
	const outputFrames = Math.round(outputDuration * options.fps)

	console.log(`Input: ${options.input}`)
	console.log(
		`Source: ${probe.resolution.width}x${probe.resolution.height}, ${probe.duration.toFixed(
			3
		)}s, ${probe.frameRate.toFixed(3)} fps, ${probe.frameCount} frames, ${formatBytes(probe.size)}`
	)
	console.log(
		`Output target: ${options.slowmo}x slow-mo, ${options.fps} fps, ${outputDuration.toFixed(
			3
		)}s, about ${outputFrames} frames`
	)
}

function printEstimate(response: CreateResponse) {
	console.log(`Request ID: ${response.requestId}`)

	const cost = response.estimates?.cost
	const time = response.estimates?.time

	if (cost) console.log(`Estimated cost: ${cost[0]}-${cost[1]} credits`)
	if (time) console.log(`Estimated processing time: ${time[0]}-${time[1]} seconds`)
}

async function acceptAndUpload(requestId: string, input: string) {
	const accepted = await topazFetch<AcceptResponse>(`/video/${requestId}/accept`, {
		method: 'PATCH'
	})

	if (!accepted.urls?.length) {
		throw new Error(`Topaz did not return upload URLs: ${JSON.stringify(accepted)}`)
	}

	console.log(`Accepted request ${requestId}; uploading ${accepted.urls.length} part(s)`)

	const uploadResults = await uploadParts(input, accepted.urls)
	const md5Hash = createHash('md5').update(await readFile(input)).digest('hex')

	await topazFetch(`/video/${requestId}/complete-upload/`, {
		method: 'PATCH',
		headers: {
			'content-type': 'application/json'
		},
		body: JSON.stringify({
			md5Hash,
			uploadResults
		})
	})

	console.log(`Queued processing for ${requestId}`)
	console.log(`Check status: bun scripts/topaz-slowmo.ts status ${requestId}`)
}

async function uploadParts(input: string, urls: string[]) {
	const file = Bun.file(input)
	const partSize = Math.ceil(file.size / urls.length)
	const results: UploadResult[] = []

	for (const [index, url] of urls.entries()) {
		const partNum = index + 1
		const start = index * partSize
		const end = Math.min(file.size, start + partSize)
		const body = file.slice(start, end)

		console.log(`Uploading part ${partNum}/${urls.length} (${formatBytes(body.size)})`)

		const response = await fetch(url, {
			method: 'PUT',
			headers: {
				'Content-Type': 'video/mp4'
			},
			body
		})

		if (!response.ok) {
			throw new Error(`Upload part ${partNum} failed with ${response.status}: ${await response.text()}`)
		}

		const eTag = response.headers.get('etag')
		if (!eTag) throw new Error(`Upload part ${partNum} did not return an ETag`)

		results.push({ partNum, eTag })
	}

	return results
}

async function printStatus(options: Options) {
	if (!options.requestId) throw new Error('status requires a request ID')

	const status = await topazFetch<Record<string, unknown>>(`/video/${options.requestId}/status`)
	console.log(JSON.stringify(status, null, 2))

	if (!options.download) return

	const downloadUrl = findDownloadUrl(status)
	if (!downloadUrl) {
		throw new Error('Could not find a download URL in the status response yet')
	}

	console.log(`Downloading result to ${options.download}`)

	const response = await fetch(downloadUrl)
	if (!response.ok) {
		throw new Error(`Download failed with ${response.status}: ${await response.text()}`)
	}

	await Bun.write(options.download, response)
	console.log(`Saved ${options.download}`)
}

function findDownloadUrl(value: unknown): string | undefined {
	if (typeof value === 'string' && /^https?:\/\//.test(value)) return value
	if (!value || typeof value !== 'object') return undefined

	for (const item of Object.values(value)) {
		const found = Array.isArray(item)
			? item.map(findDownloadUrl).find(Boolean)
			: findDownloadUrl(item)

		if (found) return found
	}
}

function formatBytes(bytes: number) {
	const mb = bytes / 1024 / 1024
	return `${mb.toFixed(1)} MB`
}

async function main() {
	const options = parseArgs(process.argv.slice(2))
	const key = getApiKey()
	console.log(`Using TOPAZ ${maskKey(key)}`)

	if (options.command === 'status') {
		await printStatus(options)
		return
	}

	const response = await createRequest(options)
	if (!response.requestId) throw new Error('Topaz did not return a request ID')

	if (options.command === 'submit') {
		await acceptAndUpload(response.requestId, options.input)
		return
	}

	console.log('')
	console.log('Estimate only. To spend credits and upload, rerun with:')
	console.log(
		`  bun scripts/topaz-slowmo.ts submit --input ${options.input} --slowmo ${options.slowmo} --fps ${options.fps}`
	)
}

main().catch((err) => {
	console.error('\x1b[31m✗\x1b[0m', err.message)
	process.exit(1)
})

